    """Creates a 3x3 block with val at all four corners"""
    return [
        [val, 0, val],
        [0, 0, 0],
        [val, 0, val]
    ]

def zero_pattern(val):
    """Creates a 3x3 block of zeros"""
    return [
        [0, 0, 0],
        [0, 0, 0],
        [0, 0, 0]
    ]

